WITH "__duckstream_0" AS (SELECT t.c0 AS c0, t.c1 AS c1, t.c4 AS c2, t.c2 AS c3, CAST((CAST(t.c3 AS BIGINT) + CAST(2 AS INTEGER)) AS BIGINT) AS c4, CAST((t.c2 * CAST(2.0 AS DOUBLE)) AS DOUBLE) AS c5, CASE WHEN (t.c6 IS NULL) THEN CAST(0 AS INTEGER) ELSE t.c6 END AS c6, COALESCE(t.c3, CAST(0 AS INTEGER)) AS c7 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, l.c4 AS c4, r.c0 AS c5, r.c1 AS c6 FROM (SELECT "id" AS c0, "day" AS c1, "rating" AS c2, "score" AS c3, "price" AS c4 FROM "teams") l LEFT JOIN (SELECT "id" AS c0, "position" AS c1 FROM "standings") r ON (l.c0 = r.c0)) t)
SELECT CAST(result.c0 AS UUID) AS "id", CAST(result.c1 AS DATE) AS "day", CAST(result.c2 AS DECIMAL(18,2)) AS "price", CAST(result.c3 AS DOUBLE) AS "rating", CAST(result.c4 AS BIGINT) AS "adjusted", CAST(result.c5 AS DOUBLE) AS "doubled", CAST(result.c6 AS INTEGER) AS "position", CAST(result.c7 AS INTEGER) AS "score" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7 FROM "__duckstream_0" v) result;
